esac
cat "$RM5_DIR/sql/$file" | k -n "$RM5_NAMESPACE" exec -i postgres-0 -- sh -c 'export PGPASSWORD="$POSTGRES_PASSWORD"; exec psql --no-psqlrc -h 127.0.0.1 -U rm5_admin -d komtas_rm5 -v ON_ERROR_STOP=1'
