sql/seed.sql:
\getenv bi_password PBI_PASSWORD
\getenv dbt_password DBT_PASSWORD
BEGIN;
CREATE SCHEMA IF NOT EXISTS raw;
CREATE SCHEMA IF NOT EXISTS dwh;
CREATE TABLE IF NOT EXISTS raw.dim_date (
    date_key date PRIMARY KEY,
    year_number integer NOT NULL,
    month_number integer NOT NULL,
    month_start date NOT NULL
);
CREATE TABLE IF NOT EXISTS raw.dim_product (
    product_key integer PRIMARY KEY,
    product_name text NOT NULL,
    category text NOT NULL,
    liters_per_unit numeric(8,3) NOT NULL CHECK (liters_per_unit > 0)
);
CREATE TABLE IF NOT EXISTS raw.dim_outlet (
    outlet_key integer PRIMARY KEY,
    outlet_name text NOT NULL,
    country text NOT NULL,
    channel text NOT NULL,
    distributor_key integer NOT NULL,
    distributor_name text NOT NULL
);
CREATE TABLE IF NOT EXISTS raw.dim_promotion (
    promotion_key integer PRIMARY KEY,
    promotion_name text NOT NULL
);
INSERT INTO raw.dim_date
SELECT d::date, 2025, extract(month FROM d)::integer, date_trunc('month',d)::date
FROM generate_series(timestamp '2025-01-01',timestamp '2025-02-28',interval '1 day') d
ON CONFLICT DO NOTHING;
INSERT INTO raw.dim_product VALUES
(1,'Sparkling Water 1L','Water',1.000),
(2,'Juice 500ml','Juice',0.500),
(3,'Soft Drink 330ml','Soft Drink',0.330)
ON CONFLICT DO NOTHING;
INSERT INTO raw.dim_outlet
SELECT n, 'Outlet '||n,
       CASE WHEN n <= 6 THEN 'TR' ELSE 'DE' END,
       (ARRAY['HoReCa','Retail','Online'])[1+(n-1)%3],
       1+(n-1)/3, 'Distributor '||(1+(n-1)/3)
FROM generate_series(1,12) n
ON CONFLICT DO NOTHING;
INSERT INTO raw.dim_promotion VALUES
(0,'No promotion'),(1,'HoReCa 10 percent'),(2,'Retail 5 percent')
ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS raw.sales_line (
    sales_line_key bigint PRIMARY KEY,
    sale_date date NOT NULL,
    outlet_key integer NOT NULL,
    product_key integer NOT NULL,
    promotion_key integer NOT NULL,
    sold_units integer NOT NULL CHECK (sold_units > 0),
    returned_units integer NOT NULL CHECK (returned_units BETWEEN 0 AND sold_units),
    unit_price_eur numeric(12,2) NOT NULL,
    discount_rate numeric(5,4) NOT NULL,
    source_reference text NOT NULL
);
INSERT INTO raw.sales_line
SELECT ((d.date_key-date '2025-01-01')*1000+o.outlet_key*10+p.product_key)::bigint,
       d.date_key,o.outlet_key,p.product_key,
       CASE o.channel WHEN 'HoReCa' THEN 1 WHEN 'Retail' THEN 2 ELSE 0 END,
       CASE WHEN o.channel='HoReCa' AND d.month_number=2 THEN 6 ELSE 10 END,
       CASE WHEN o.channel='HoReCa' THEN CASE WHEN d.month_number=2 THEN 2 ELSE 1 END ELSE 0 END,
       (p.product_key+1)::numeric,
       CASE o.channel WHEN 'HoReCa' THEN 0.10 WHEN 'Retail' THEN 0.05 ELSE 0 END,
       'SYNTH-RM5-'||d.date_key||'-'||o.outlet_key||'-'||p.product_key
FROM raw.dim_date d CROSS JOIN raw.dim_outlet o CROSS JOIN raw.dim_product p
WHERE extract(day FROM d.date_key)<=28
ON CONFLICT DO NOTHING;
SELECT format('CREATE ROLE rm5_bi LOGIN PASSWORD %L', :'bi_password') WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='rm5_bi')
\gexec
SELECT format('ALTER ROLE rm5_bi PASSWORD %L', :'bi_password')
\gexec
SELECT format('CREATE ROLE rm5_dbt LOGIN PASSWORD %L', :'dbt_password') WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='rm5_dbt')
\gexec
SELECT format('ALTER ROLE rm5_dbt PASSWORD %L', :'dbt_password')
\gexec
ALTER ROLE rm5_bi SET default_transaction_read_only=on;
GRANT CONNECT ON DATABASE komtas_rm5 TO rm5_bi,rm5_dbt;
GRANT USAGE ON SCHEMA raw TO rm5_dbt;
GRANT SELECT ON ALL TABLES IN SCHEMA raw TO rm5_dbt;
GRANT USAGE,CREATE ON SCHEMA dwh TO rm5_dbt;
GRANT USAGE ON SCHEMA dwh TO rm5_bi;
ALTER DEFAULT PRIVILEGES FOR ROLE rm5_dbt IN SCHEMA dwh GRANT SELECT ON TABLES TO rm5_bi;
COMMIT;
SELECT 'RM5 raw seed complete' AS status,count(*) AS rows FROM raw.sales_line;

sql/verify.sql:
\pset pager off
BEGIN READ ONLY;
DO $$
DECLARE
    actual numeric;
BEGIN
    SELECT count(*) INTO actual FROM dwh.fact_sales;
    IF actual<>2016 THEN RAISE EXCEPTION 'Expected 2016 fact rows, got %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-01-01';
    IF actual<>27820.80 THEN RAISE EXCEPTION 'January revenue mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-02-01';
    IF actual<>23284.80 THEN RAISE EXCEPTION 'February revenue mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-01-01' AND channel='HoReCa';
    IF actual<>8164.80 THEN RAISE EXCEPTION 'January HoReCa mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-02-01' AND channel='HoReCa';
    IF actual<>3628.80 THEN RAISE EXCEPTION 'February HoReCa mismatch: %',actual; END IF;
    SELECT sum(net_volume_liters) INTO actual FROM dwh.v_sales_detail
    WHERE month_start=date '2025-02-01' AND channel='HoReCa';
    IF actual<>819.840 THEN RAISE EXCEPTION 'February HoReCa volume mismatch: %',actual; END IF;
    SELECT count(DISTINCT country) INTO actual FROM dwh.dim_outlet;
    IF actual<>2 THEN RAISE EXCEPTION 'Country count mismatch'; END IF;
    IF has_table_privilege(current_user,'dwh.fact_sales','INSERT') THEN
        RAISE EXCEPTION 'BI user must not have INSERT permission';
    END IF;
    RAISE NOTICE 'PASS: row counts, reference totals, volume and BI read-only access';
END $$;
SELECT month_start,channel,
       sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) AS net_revenue_eur,
       sum(net_volume_liters) AS volume_liters,
       round(sum(gross_revenue_eur-discount_amount_eur-return_amount_eur)/nullif(sum(net_volume_liters),0),6) AS average_price_eur_per_liter,
       count(DISTINCT outlet_key) FILTER (WHERE sold_units>returned_units) AS active_outlets
FROM dwh.v_sales_detail
GROUP BY month_start,channel ORDER BY month_start,channel;
COMMIT;
